/** Preserve signed sub-cent evidence without passing through Number or currency rounding. */
const exactSignedDecimal = ({ coefficient, scale }: MortgageDecimal): string => {
  const negative = coefficient.startsWith('-')
  const digits = negative ? coefficient.slice(1) : coefficient
  const sign = negative ? '-' : '+'
  if (scale > 40) return `${sign}${digits}e-${scale}`
  const padded = digits.padStart(scale + 1, '0')
  return sign + (scale ? `${padded.slice(0, -scale)}.${padded.slice(-scale)}` : padded)
}
